    public final boolean checkHrmDistributeValid() {
        return (this.hrExtremeDuration == null || this.hrAnaerobicDuration == null || this.hrAerobicDuration == null || this.hrFatBurningDuration == null || this.hrWarmUpDuration == null) ? false : true;
    }

    public final boolean checkPaceDistributeValid() {
        return (this.onePaceZoneDuration == null || this.twoPaceZoneDuration == null || this.threePaceZoneDuration == null || this.fourPaceZoneDuration == null || this.fivePaceZoneDuration == null) ? false : true;
    }

    public final boolean divingInPositionValid() {
        Float f;
        Float f2 = this.waterInletLatitude;
        return (f2 == null || Intrinsics.areEqual(f2, 10000.0f) || (f = this.waterInletLongitude) == null || Intrinsics.areEqual(f, 10000.0f)) ? false : true;
    }

    public final boolean divingOutPositionValid() {
        Float f;
        Float f2 = this.waterOutletLatitude;
        return (f2 == null || Intrinsics.areEqual(f2, 10000.0f) || (f = this.waterOutletLongitude) == null || Intrinsics.areEqual(f, 10000.0f)) ? false : true;
    }

